; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: zxn (ZX Spectrum Next - direct hardware (native)), starts in normal mode
; ============================================================

			DEVICE ZXSPECTRUMNEXT		; for SAVENEX at the end
			MMU 0 5, 16			; #0000-#BFFF: pages 16-21 (banks 8, 9, 10)
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 1		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
; the ZX Spectrum Next: NTC_ZXN defined (a DEFINE - sjasmplus's IFDEF tests those, not labels)
			DEFINE NTC_ZXN
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			di
			ld sp, #C000		; the platform's own real stack
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld ix, ntc_go
			jp ntc_plat_irqon		; interrupt handler for normal mode
ntc_go:
			ld sp, main_thread
			ret

			IF ($ < 32768) && (ntc_rg1_e - ntc_rg1 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
ntc_rg1:
; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_scrinit		; mode 1, ROMs off, clear screen
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; bank_proof.bas 13: Mode 2
			dw kw_model, 2

			; bank_proof.bas 14: Ints 0
			dw p_ints_c, lit_0

			; bank_proof.bas 15: Print "CyborgOS-Next MMU banking proof"
			dw kw_printzoscii
			dw glyph_43, glyph_79, glyph_62, glyph_6F, glyph_72, glyph_67, glyph_4F, glyph_53
			dw glyph_2D, glyph_4E, glyph_65, glyph_78, glyph_74, glyph_20, glyph_4D, glyph_4D
			dw glyph_55, glyph_20, glyph_62, glyph_61, glyph_6E, glyph_6B, glyph_69, glyph_6E
			dw glyph_67, glyph_20, glyph_70, glyph_72, glyph_6F, glyph_6F, glyph_66, 1
			dw 0		; "CyborgOS-Next MMU banking proof\n"

			; bank_proof.bas 16: Print
			dw kw_printnl

			; bank_proof.bas 19: Banks.MapWin 22 : Poke W0, 65 : Poke W1, 97      ' bank 22: 'A' low 8K, 'a' high 8K
			dw p_banks_mapwin_c, lit_22
			dw kw_ltolptr8, 65, 16384
			dw kw_ltolptr8, 97, 24576

			; bank_proof.bas 20: Banks.MapWin 23 : Poke W0, 66 : Poke W1, 98      ' bank 23: 'B' low 8K, 'b' high 8K
			dw p_banks_mapwin_c, lit_23
			dw kw_ltolptr8, 66, 16384
			dw kw_ltolptr8, 98, 24576

			; bank_proof.bas 21: Banks.MapWin 22
			dw p_banks_mapwin_c, lit_22

			; bank_proof.bas 22: Print "bank 22 (both 8K): "; Chr$(Peek(W0)); Chr$(Peek(W1)); "  (want Aa)"
			dw kw_lptrtov8, 16384, tmp0
			dw kw_strchr, stmp0, tmp0
			dw kw_printzoscii
			dw glyph_62, glyph_61, glyph_6E, glyph_6B, glyph_20, glyph_32, glyph_32, glyph_20
			dw glyph_28, glyph_62, glyph_6F, glyph_74, glyph_68, glyph_20, glyph_38, glyph_4B
			dw glyph_29, glyph_3A, glyph_20, 0		; "bank 22 (both 8K): "
			dw kw_printstrvar, stmp0
			dw kw_lptrtov8, 24576, tmp0
			dw kw_strchr, stmp0, tmp0
			dw kw_printstrvar, stmp0
			dw kw_printzoscii
			dw glyph_20, glyph_20, glyph_28, glyph_77, glyph_61, glyph_6E, glyph_74, glyph_20
			dw glyph_41, glyph_61, glyph_29, 1, 0		; "  (want Aa)\n"

			; bank_proof.bas 23: Banks.MapWin 23
			dw p_banks_mapwin_c, lit_23

			; bank_proof.bas 24: Print "bank 23 (both 8K): "; Chr$(Peek(W0)); Chr$(Peek(W1)); "  (want Bb)"
			dw kw_lptrtov8, 16384, tmp0
			dw kw_strchr, stmp0, tmp0
			dw kw_printzoscii
			dw glyph_62, glyph_61, glyph_6E, glyph_6B, glyph_20, glyph_32, glyph_33, glyph_20
			dw glyph_28, glyph_62, glyph_6F, glyph_74, glyph_68, glyph_20, glyph_38, glyph_4B
			dw glyph_29, glyph_3A, glyph_20, 0		; "bank 23 (both 8K): "
			dw kw_printstrvar, stmp0
			dw kw_lptrtov8, 24576, tmp0
			dw kw_strchr, stmp0, tmp0
			dw kw_printstrvar, stmp0
			dw kw_printzoscii
			dw glyph_20, glyph_20, glyph_28, glyph_77, glyph_61, glyph_6E, glyph_74, glyph_20
			dw glyph_42, glyph_62, glyph_29, 1, 0		; "  (want Bb)\n"

			; bank_proof.bas 27: bad = 0
			dw kw_ztov, var_bad

			; bank_proof.bas 28: For i = 0 To 3
			dw kw_ztov, var_i
for1_t:

			; bank_proof.bas 29: Banks.MapWin Banks.SlotBank(0, i) : Poke W0, 48 + i * 2 : Poke W1, 49 + i * 2
			dw p_banks_slotbank_c, lit_0, var_i
			dw kw_vtov, var_banks_slotbank_slotbank, tmp0
			dw p_banks_mapwin_c, tmp0
			dw kw_2x, var_i, tmp2
			dw kw_addl, tmp2, 48, tmp1
			dw kw_vtolptr8, tmp1, 16384
			dw kw_2x, var_i, tmp2
			dw kw_addl, tmp2, 49, tmp1
			dw kw_vtolptr8, tmp1, 24576

			; bank_proof.bas 30: Next
			dw kw_next1l_n, var_i, 3, for1_t
for1_e:

			; bank_proof.bas 31: For i = 0 To 3
			dw kw_ztov, var_i
for2_t:

			; bank_proof.bas 32: Banks.MapWin Banks.SlotBank(0, i)
			dw p_banks_slotbank_c, lit_0, var_i
			dw kw_vtov, var_banks_slotbank_slotbank, tmp0
			dw p_banks_mapwin_c, tmp0

			; bank_proof.bas 33: If Peek(W0) <> 48 + i * 2 Then bad = bad + 1
			dw kw_lptrtov8, 16384, tmp0
			dw kw_2x, var_i, tmp2
			dw kw_addl, tmp2, 48, tmp1
			dw kw_cpnevv, tmp0, tmp1
			dw kw_goto_iffalse_n, if3_1
			dw kw_inc, var_bad
if3_1:

			; bank_proof.bas 34: If Peek(W1) <> 49 + i * 2 Then bad = bad + 1
			dw kw_lptrtov8, 24576, tmp0
			dw kw_2x, var_i, tmp2
			dw kw_addl, tmp2, 49, tmp1
			dw kw_cpnevv, tmp0, tmp1
			dw kw_goto_iffalse_n, if4_1
			dw kw_inc, var_bad
if4_1:

			; bank_proof.bas 35: Next
			dw kw_next1l_n, var_i, 3, for2_t
for2_e:

			; bank_proof.bas 36: Print
			dw kw_printnl

			; bank_proof.bas 37: Print "64K slot = 4 banks x 2 x 8K = 8 pages: "; 8 - bad; " of 8 isolated"
			dw kw_sublv, 8, var_bad, tmp0
			dw kw_printzoscii
			dw glyph_36, glyph_34, glyph_4B, glyph_20, glyph_73, glyph_6C, glyph_6F, glyph_74
			dw glyph_20, glyph_3D, glyph_20, glyph_34, glyph_20, glyph_62, glyph_61, glyph_6E
			dw glyph_6B, glyph_73, glyph_20, glyph_78, glyph_20, glyph_32, glyph_20, glyph_78
			dw glyph_20, glyph_38, glyph_4B, glyph_20, glyph_3D, glyph_20, glyph_38, glyph_20
			dw glyph_70, glyph_61, glyph_67, glyph_65, glyph_73, glyph_3A, glyph_20, 0		; "64K slot = 4 banks x 2 x 8K = 8 pages: "
			dw kw_printint, tmp0
			dw kw_printzoscii
			dw glyph_20, glyph_6F, glyph_66, glyph_20, glyph_38, glyph_20, glyph_69, glyph_73
			dw glyph_6F, glyph_6C, glyph_61, glyph_74, glyph_65, glyph_64, 1, 0		; " of 8 isolated\n"

			; bank_proof.bas 38: If bad = 0 Then Print "BANKING OK" Else Print "BANKING FAIL"
			dw kw_cpeqvl, var_bad, 0
			dw kw_goto_iffalse_n, if5_1
			dw kw_printzoscii
			dw glyph_42, glyph_41, glyph_4E, glyph_4B, glyph_49, glyph_4E, glyph_47, glyph_20
			dw glyph_4F, glyph_4B, 1, 0		; "BANKING OK\n"
			dw if5_e_go
if5_1:
			dw kw_printzoscii
			dw glyph_42, glyph_41, glyph_4E, glyph_4B, glyph_49, glyph_4E, glyph_47, glyph_20
			dw glyph_46, glyph_41, glyph_49, glyph_4C, 1, 0		; "BANKING FAIL\n"
if5_e:

			; bank_proof.bas 40: Banks.MapWin 9                         ' the program's own pages (bank 9) back in the window
			dw p_banks_mapwin_c, lit_9

			; bank_proof.bas 41: Ints 1
			dw p_ints_c, lit_1

			; bank_proof.bas 42: End
			dw kw_stop

