            ld b, #25		; Banks.cls 24
            out (c), d                      ; = page [25]
            ld b, #24		; Banks.cls 26
            ld a, #53		; Banks.cls 27
            out (c), a                      ; select MMU slot 3 (NextReg #53) [28]
            inc d		; Banks.cls 29
            ld b, #25		; Banks.cls 30
            out (c), d                      ; = page + 1 [31]
